+
+describe("view_order_reversed", () => {
+    const setReversed = (state, value: boolean) =>
+        reduceFlows(
+            state,
+            // @ts-expect-error partial payload
+            OPTIONS_UPDATE({ view_order_reversed: { value } }),
+        );
+    const add = (state, id: string) =>
+        reduceFlows(
+            state,
+            flowActions.FLOWS_ADD({
+                flow: { ...TFlow(), id },
+                matching_filters: {},
+            }),
+        );
+    const ids = (state) => state.view.map((f) => f.id);
+
+    it("reads the option from OPTIONS_RECEIVE and OPTIONS_UPDATE", () => {
+        let state = reduceFlows(
+            undefined,
+            // @ts-expect-error partial payload
+            OPTIONS_RECEIVE({ view_order_reversed: { value: true } }),
+        );
+        expect(state.viewOrderReversed).toBe(true);
+        state = setReversed(state, false);
+        expect(state.viewOrderReversed).toBe(false);
+    });
+
+    it("inserts new flows at the front when reversed", () => {
+        let state = setReversed(undefined, true);
+        for (const id of ["a", "b", "c"]) state = add(state, id);
+        expect(ids(state)).toEqual(["c", "b", "a"]);
+    });
+
+    it("appends new flows when not reversed", () => {
+        let state = setReversed(undefined, false);
+        for (const id of ["a", "b", "c"]) state = add(state, id);
+        expect(ids(state)).toEqual(["a", "b", "c"]);
+    });
+
+    it("lets an active column sort take precedence", () => {
+        let state = setReversed(undefined, true);
+        state = reduceFlows(
+            state,
+            flowActions.setSort({ column: "path", desc: false }),
+        );
+        state = add(state, "a");
+        state = add(state, "b");
+        // Equal sort keys keep insertion order, unaffected by the option.
+        expect(ids(state)).toEqual(["a", "b"]);
+    });
+});
